  function isLikeContent(content) {
    return content === "+" || content === "";
  }
  function isUnlikeContent(content) {
    return content === "-";
  }
  function netLikesByPubkey(events) {
    const latestByPubkey = /* @__PURE__ */ new Map();
    for (const event of events) {
      if (!event?.pubkey) continue;
      const existing = latestByPubkey.get(event.pubkey);
      if (!existing || event.created_at > existing.created_at || event.created_at === existing.created_at && event.id > existing.id) {
        latestByPubkey.set(event.pubkey, event);
      }
    }
    const likeDetails = [];
    let likedCount = 0;
    let dislikedCount = 0;
    for (const event of latestByPubkey.values()) {
      likeDetails.push({
        authorPubkey: event.pubkey,
        date: new Date(event.created_at * 1e3),
        content: event.content
      });
      if (isUnlikeContent(event.content)) {
        dislikedCount++;
      } else if (isLikeContent(event.content)) {
        likedCount++;
      }
    }
    likeDetails.sort((a, b) => b.date.getTime() - a.date.getTime());
    return {
      // Social proof = number of distinct pubkeys whose latest reaction is a like
      totalCount: likedCount,
      likeDetails,
      likedCount,
      dislikedCount
    };
  }

